@startuml
class Customer {
  +name : string
  +surname : string
  +email : string
  +telephone : string
  +homeAddress : string
}

class Order {
  +totalCost : float
  +estimatedDeliveryTime : time
  +status : string
}

class Dish {
  +preparationTime : time
}

class Payment {
  +creditCardInfo : string
  +isSuccessful : boolean
}

class Kitchen {
  +currentWorkload : int
}

class DeliveryDepartment {
  +status : string
}

Customer "1" -- "*" Order : places
Order "1" *-- "1..*" Dish : contains
Order "1" -- "0..1" Payment : processed by
Order "1" -- "1" Kitchen : sent to
Order "1" -- "1" DeliveryDepartment : delivered by
@enduml

